  let keysFreq = smoothStep(300.0, 600.0, hz) * (1.0 - smoothStep(7000.0, 9000.0, hz));
  let keysW = keysFreq * (0.4 + 0.6 * sideRatio);
  let otherW = smoothStep(4000.0, 6000.0, hz) * 0.6 + 0.15;

