  let wBass = bassW / sum;
  let wVocal = vocalW / sum;
  let wGuitar = guitarW / sum;
  let wKeys = keysW / sum;
  let wOther = otherW / sum;

  let mid = midMag[idx];
  vocalOut[idx] = m * wVocal;
  bassOut[idx] = mid * wBass;
  guitarOut[idx] = s * 0.65 + m * wGuitar * 0.5;
  keysOut[idx] = s * 0.45 + m * wKeys * 0.55;
